    VIEWPORT_MARKER_KEY: VIEWPORT_MARKER_KEY,
    STEADY_HIDE_MS: STEADY_HIDE_MS,
    STEADY_FADE_MS: STEADY_FADE_MS,
    STEADY_DRIFT_PX: STEADY_DRIFT_PX,
